import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.BDKIrnCI.js";const u=JSON.parse('{"title":"Code style","description":"","frontmatter":{},"headers":[],"relativePath":"guides/code-style.md","filePath":"docs/code-style.md"}'),n={name:"guides/code-style.md"};function i(c,e,r,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="code-style" tabindex="-1">Code style <a class="header-anchor" href="#code-style" aria-label="Permalink to &quot;Code style&quot;">​</a></h1><p><code>pnpm lint</code> runs two linters, and CI runs the same command.</p><h2 id="biome" tabindex="-1">Biome <a class="header-anchor" href="#biome" aria-label="Permalink to &quot;Biome&quot;">​</a></h2><p><a href="https://biomejs.dev" target="_blank" rel="noreferrer">Biome</a> formats and lints everything (<code>biome.json</code>). <code>pnpm lint:fix</code> applies what it can fix. The <a href="./agent-tooling">agent check runner</a> checks changed files without applying fixes, so it can safely inspect a working tree that contains other people&#39;s edits. Notable rules from the config: single quotes, four-space indent, shorthand array types (<code>T[]</code>), <code>import type</code> for types, and a warning on <code>any</code>.</p><h2 id="jsdoc" tabindex="-1">JSDoc <a class="header-anchor" href="#jsdoc" aria-label="Permalink to &quot;JSDoc&quot;">​</a></h2><p>Biome has no rule for documentation, so ESLint with <code>eslint-plugin-jsdoc</code> (<code>eslint.config.mjs</code>) does that one job. It requires a JSDoc <strong>description</strong> on public code:</p><ul><li>exported functions, classes, interfaces, type aliases, enums and constants,</li><li>public methods of exported classes.</li></ul><p>It does not require <code>@param</code> and <code>@returns</code> tags, since TypeScript already types them. Add them when they say something the signature doesn&#39;t, such as units, defaults or what a thrown error means. If you write a <code>@param</code>, its name must match a real parameter, and tags don&#39;t take <code>{types}</code>.</p><p>Tests (including the <code>testing/</code> folders of shared packages), config files and generator templates are exempt, as are private helpers. A good description says what the thing is for, not what its name says.</p><h2 id="console-log-colors" tabindex="-1">Console log colors <a class="header-anchor" href="#console-log-colors" aria-label="Permalink to &quot;Console log colors&quot;">​</a></h2><p>Use <code>colorLogValue</code> from <code>@pumpkin-plugins/plugin-kit/logger</code> to color a few useful values in console messages. Keep the surrounding message plain and color only values that help someone scan it, such as names and URLs in cyan, versions in green, and ports, UUIDs or other identifiers in yellow. Do not add ANSI escape sequences directly at log call sites.</p><p>Keep this palette aligned with the Pumpkin server version pinned in <a href="../tools/test-harness/src/pumpkin-version.ts"><code>tools/test-harness/src/pumpkin-version.ts</code></a>. Pumpkin uses cyan for plugin names, green for versions and bold yellow for permissions in its <a href="https://github.com/Pumpkin-MC/Pumpkin/blob/0.2.0%2B26.3-26.51/crates/pumpkin/src/plugin/mod.rs#L493-L504" target="_blank" rel="noreferrer">plugin permission prompt</a>. Its <a href="https://github.com/Pumpkin-MC/Pumpkin/blob/0.2.0%2B26.3-26.51/crates/pumpkin/src/logging.rs#L281-L335" target="_blank" rel="noreferrer">rolling log file layer</a> removes ANSI codes before writing files, leaving the console color useful without adding escape codes to saved logs. When the pinned server version changes, check these Pumpkin source references and update this convention if its palette or log handling changes.</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><ul><li>Keep files small and focused. A file that does two things should be two files. Around 150 lines is a prompt to look for the seam, not a hard limit.</li><li>Separate logic from the host. Pure logic (parsing, ordering, protocol state machines) goes in plain modules that take their dependencies as arguments. Code that touches Pumpkin or WASI is a thin adapter behind an interface, such as <code>DataFiles</code> or <code>Transport</code>. That keeps almost everything unit-testable and leaves only the adapters for the real-server tests.</li><li>Group a plugin&#39;s <code>src/</code> by concern (<code>config/</code>, <code>packs/</code>, <code>web/</code>, <code>platform/</code>) rather than by kind of file.</li><li>Share what more than one plugin needs through a package in <code>tools/</code>, as <code>@pumpkin-plugins/config</code> does, instead of copying it.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li>Unit tests (<code>*.test.ts</code>) sit beside the code. Real-server tests (<code>*.itest.ts</code>) live in <code>test/</code>, one file per concern. See <a href="./testing">Testing</a>.</li><li>Test behavior, including the failure paths: invalid input, missing files, clients that hang up. Don&#39;t assert things the types already guarantee.</li><li>Generate fixtures in code (for example <code>.mcpack</code> archives) instead of committing binaries.</li></ul><h2 id="package-metadata" tabindex="-1">Package metadata <a class="header-anchor" href="#package-metadata" aria-label="Permalink to &quot;Package metadata&quot;">​</a></h2><p>Every <code>package.json</code> (the root, each plugin, each tool) carries the same author, contributors, homepage, repository, bugs and funding fields, and a description of at most 70 characters. Tools that export code also set <code>sideEffects</code>, <code>module</code>, <code>types</code>, <code>files</code> and <code>publishConfig</code>. <code>node scripts/package-metadata.mjs</code> checks it and <code>--fix</code> writes everything that can be derived; <code>pnpm gen</code> already generates plugins that pass. The homepage of a package is its folder&#39;s README on <code>master</code>. Packages use MIT by default. A package with its own <code>LICENSE</code>, <code>LICENSE.md</code> or <code>LICENSE.txt</code> file keeps the license declared in its <code>package.json</code>, including when metadata is fixed.</p><h2 id="docs-match-the-code" tabindex="-1">Docs match the code <a class="header-anchor" href="#docs-match-the-code" aria-label="Permalink to &quot;Docs match the code&quot;">​</a></h2><p>A change that makes a doc wrong is not finished until the doc is fixed, and the checks keep it honest:</p><ul><li><code>pnpm readme:check</code> fails when generated README content is stale: plugin documentation, root action/package tables, or action input/output tables from <code>action.yml</code>.</li><li><code>pnpm check</code> runs <code>scripts/check-docs.mjs</code>, which fails when a README is missing from a package, a link, heading or repo path in the docs doesn&#39;t exist, a <code>pnpm</code> command isn&#39;t a script, a page isn&#39;t in the docs index, a root script isn&#39;t documented, or a CI job isn&#39;t in the CI table.</li><li>Documentation that can be derived from code is derived: commands are declared once with <code>defineCommands</code> and listed in the README from the same declaration, permission names are typed against the ones Pumpkin knows, and settings come from the config schema.</li></ul><p>What a script can&#39;t check is whether the prose is right. The pull request template asks for it, so read the docs you touched, and the ones that describe what you changed (search <code>docs/</code> and the READMEs for the names you renamed).</p>',22)])])}const m=o(n,[["render",i]]);export{u as __pageData,m as default};
